// --- xray-runner.js — Minimal Xray runner for BABA Tunnel (BBT) ---
//
// Manages the lifecycle of the Xray-core binary strictly for BBT's Fastly MASQUE tunnel.
// Does not include any logic for VLESS/VMess, reality, shadowsocks, gRPC or other extraneous engines.
// Spawns xray.exe with the JSON config generated by bbt-core.config() and verifies port readiness.

'use strict';

const fs = require('fs');
const os = require('os');
const net = require('net');
const path = require('path');
const { spawn } = require('child_process');

const SOCKS_PORT = 10808;
const HTTP_PORT = 10809;

let xrayProcess = null;
let currentUri = null;
let currentConfigPath = null;

/** Locate xray.exe binary strictly from core/, packaged resources, AppData, or BBT_XRAY_PATH */
function getBinaryPath() {
    // 1. Environment variable override
    const envPath = process.env.BBT_XRAY_PATH || process.env.FENIX_XRAY_PATH || process.env.XRAY_PATH;
    if (envPath) {
        if (fs.existsSync(envPath)) return envPath;
        throw new Error(`Configured Xray binary not found at BBT_XRAY_PATH: "${envPath}"`);
    }

    // 2. Local core/ directory inside project
    const local = path.join(__dirname, 'core', 'xray.exe');
    if (fs.existsSync(local)) return local;

    // 3. Current working directory core/
    const cwdCore = path.join(process.cwd(), 'core', 'xray.exe');
    if (fs.existsSync(cwdCore)) return cwdCore;

    // 4. Electron packaged resources (resources/core/xray.exe or root/core/xray.exe)
    if (process.resourcesPath) {
        const inRes = path.join(process.resourcesPath, 'core', 'xray.exe');
        if (fs.existsSync(inRes)) return inRes;
        const nextToRes = path.join(process.resourcesPath, '..', 'core', 'xray.exe');
        if (fs.existsSync(nextToRes)) return nextToRes;
        const unpacked = path.join(process.resourcesPath, 'app.asar.unpacked', 'core', 'xray.exe');
        if (fs.existsSync(unpacked)) return unpacked;
    }

    // 5. Next to running executable (installed BABA Tunnel.exe or portable temp extraction)
    if (process.execPath) {
        const nextToExe = path.join(path.dirname(process.execPath), 'core', 'xray.exe');
        if (fs.existsSync(nextToExe)) return nextToExe;
        const inExeRes = path.join(path.dirname(process.execPath), 'resources', 'core', 'xray.exe');
        if (fs.existsSync(inExeRes)) return inExeRes;
    }

    // 6. User AppData / LocalAppData directories
    for (const appDirName of ['baba-tunnel', 'fenix-vpn']) {
        const appData = path.join(process.env.APPDATA || '', appDirName, 'core', 'xray.exe');
        if (fs.existsSync(appData)) return appData;

        const localAppData = path.join(process.env.LOCALAPPDATA || '', 'Programs', appDirName, 'core', 'xray.exe');
        if (fs.existsSync(localAppData)) return localAppData;

        const localAppDataDirect = path.join(process.env.LOCALAPPDATA || '', appDirName, 'core', 'xray.exe');
        if (fs.existsSync(localAppDataDirect)) return localAppDataDirect;
    }

    // 7. Auto-detect from system development folders and cache into AppData
    const knownFallbacks = [
        path.join(process.env.USERPROFILE || '', 'Desktop', 'New folder', 'fenix-standalone', 'core', 'xray.exe'),
        path.join(process.env.USERPROFILE || '', 'Desktop', 'New folder', 'mlmvpn_windows', 'core', 'xray.exe')
    ];
    for (const fb of knownFallbacks) {
        if (fs.existsSync(fb)) {
            try {
                const srcDir = path.dirname(fb);
                const targetDir = path.join(process.env.APPDATA || '', 'baba-tunnel', 'core');
                if (!fs.existsSync(targetDir)) fs.mkdirSync(targetDir, { recursive: true });
                for (const file of ['xray.exe', 'geoip.dat', 'geosite.dat', 'sing-box.exe', 'wintun.dll']) {
                    const srcFile = path.join(srcDir, file);
                    const dstFile = path.join(targetDir, file);
                    if (fs.existsSync(srcFile) && !fs.existsSync(dstFile)) {
                        fs.copyFileSync(srcFile, dstFile);
                    }
                }
                const targetPath = path.join(targetDir, 'xray.exe');
                return fs.existsSync(targetPath) ? targetPath : fb;
            } catch (_) {
                return fb;
            }
        }
    }

    throw new Error('xray.exe binary was not found. Please place xray.exe in "core/xray.exe" or configure BBT_XRAY_PATH in .env (see docs/BUILD.md).');
}

/** Check if a local TCP port is accepting connections */
function checkPort(port, host = '127.0.0.1', timeoutMs = 500) {
    return new Promise((resolve) => {
        const socket = new net.Socket();
        let status = false;
        socket.setTimeout(timeoutMs);

        socket.on('connect', () => {
            status = true;
            socket.destroy();
        });

        socket.on('timeout', () => socket.destroy());
        socket.on('error', () => socket.destroy());
        socket.on('close', () => resolve(status));

        socket.connect(port, host);
    });
}

/** Wait for local port to become open */
async function waitForPort(port, maxWaitMs = 10000) {
    const deadline = Date.now() + maxWaitMs;
    while (Date.now() < deadline) {
        if (await checkPort(port)) return true;
        await new Promise((r) => setTimeout(r, 200));
    }
    return false;
}

/** Start Xray with the given JSON config string */
async function start(uriConfig) {
    if (!uriConfig) throw new Error('No configuration provided to Xray runner.');
    await stop();

    const bin = getBinaryPath();
    const configObj = typeof uriConfig === 'string' ? JSON.parse(uriConfig) : uriConfig;
    const configStr = JSON.stringify(configObj, null, 2);

    // Save temporary config in AppData / temp
    const tmpDir = path.join(os.tmpdir(), 'bbt-xray');
    if (!fs.existsSync(tmpDir)) fs.mkdirSync(tmpDir, { recursive: true });
    currentConfigPath = path.join(tmpDir, `config-${Date.now()}.json`);
    fs.writeFileSync(currentConfigPath, configStr, 'utf8');

    return new Promise(async (resolve, reject) => {
        let resolved = false;
        let stdoutBuf = '';
        let stderrBuf = '';

        const assetDir = path.dirname(bin);
        const childEnv = Object.assign({}, process.env, {
            XRAY_LOCATION_ASSET: assetDir,
            GOMAXPROCS: '1',
        });

        try {
            xrayProcess = spawn(bin, ['run', '-c', currentConfigPath], {
                cwd: assetDir,
                env: childEnv,
                windowsHide: true,
                stdio: ['ignore', 'pipe', 'pipe'],
            });
        } catch (err) {
            cleanupTemp();
            return reject(new Error(`Failed to spawn Xray binary at '${bin}': ${err.message}`));
        }

        currentUri = typeof uriConfig === 'string' ? uriConfig : JSON.stringify(uriConfig);

        xrayProcess.stdout.on('data', (d) => {
            stdoutBuf += d.toString();
            if (stdoutBuf.length > 8192) stdoutBuf = stdoutBuf.slice(-4096);
        });

        xrayProcess.stderr.on('data', (d) => {
            stderrBuf += d.toString();
            if (stderrBuf.length > 8192) stderrBuf = stderrBuf.slice(-4096);
        });

        xrayProcess.on('error', (err) => {
            if (!resolved) {
                resolved = true;
                cleanupTemp();
                reject(new Error(`Xray process error: ${err.message}`));
            }
        });

        xrayProcess.on('exit', (code, signal) => {
            xrayProcess = null;
            cleanupTemp();
            if (!resolved) {
                resolved = true;
                const errDetail = (stderrBuf || stdoutBuf || '').trim();
                const firstErrLine = errDetail.split('\n').find((l) => /failed|error|fatal|illegal/i.test(l)) || errDetail.slice(0, 160);
                reject(new Error(`Xray exited with code ${code}${firstErrLine ? ': ' + firstErrLine.trim() : ''}`));
            }
        });

        // Wait for SOCKS port 10808 and HTTP port 10809 to be ready
        const ready = await waitForPort(SOCKS_PORT, 8000);
        if (ready) {
            await waitForPort(HTTP_PORT, 3000).catch(() => {});
            resolved = true;
            resolve({ ok: true, pid: xrayProcess ? xrayProcess.pid : null, socksPort: SOCKS_PORT, httpPort: HTTP_PORT });
        } else {
            await stop();
            if (!resolved) {
                resolved = true;
                reject(new Error(`Xray port ${SOCKS_PORT} did not open within timeout.`));
            }
        }
    });
}

/** Stop Xray */
async function stop() {
    try { require('./xray-stats').forget(); } catch (_) {}
    if (xrayProcess) {
        try {
            xrayProcess.kill('SIGTERM');
        } catch (e) {}
        try {
            xrayProcess.kill('SIGKILL');
        } catch (e) {}
        xrayProcess = null;
    }
    currentUri = null;
    cleanupTemp();
    // Wait for port to close
    let retries = 10;
    while (retries-- > 0 && (await checkPort(SOCKS_PORT))) {
        await new Promise((r) => setTimeout(r, 100));
    }
    return { ok: true };
}

function cleanupTemp() {
    if (currentConfigPath && fs.existsSync(currentConfigPath)) {
        try { fs.unlinkSync(currentConfigPath); } catch (e) {}
        currentConfigPath = null;
    }
}

function isRunning() {
    return !!(xrayProcess && !xrayProcess.killed);
}

function getCurrentUri() {
    return currentUri;
}

function getPorts() {
    return { socks: SOCKS_PORT, http: HTTP_PORT };
}

module.exports = {
    start,
    stop,
    isRunning,
    getCurrentUri,
    getPorts,
    checkPort,
    waitForPort,
    getBinaryPath,
    SOCKS_PORT,
    HTTP_PORT,
};
